from rest_framework import generics, status
from rest_framework.permissions import AllowAny, IsAuthenticated
from rest_framework.response import Response
from rest_framework.throttling import ScopedRateThrottle
from rest_framework.views import APIView
from rest_framework_simplejwt.tokens import RefreshToken
from rest_framework_simplejwt.views import TokenObtainPairView
from rest_framework_simplejwt.exceptions import TokenError
from .serializers import RegisterSerializer, UserSerializer


class RegisterView(APIView):
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "register"

    def post(self, request):
        serializer = RegisterSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        user = serializer.save()
        refresh = RefreshToken.for_user(user)
        return Response({
            "user": UserSerializer(user).data,
            "access": str(refresh.access_token),
            "refresh": str(refresh),
        }, status=status.HTTP_201_CREATED)


class LoginView(TokenObtainPairView):
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "login"


class LogoutView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request):
        try:
            refresh = request.data.get("refresh")
            if not refresh:
                return Response({"detail": "فیلد refresh الزامی است."}, status=400)
            RefreshToken(refresh).blacklist()
            return Response({"detail": "خروج موفق"})
        except TokenError:
            return Response({"detail": "توکن نامعتبر."}, status=400)


class MeView(generics.RetrieveUpdateAPIView):
    serializer_class = UserSerializer
    permission_classes = [IsAuthenticated]

    def get_object(self):
        return self.request.user

from django.utils import timezone
from rest_framework import serializers
from .models import Category, Task


class CategorySerializer(serializers.ModelSerializer):
    tasks_count = serializers.IntegerField(read_only=True)

    class Meta:
        model = Category
        fields = ["id", "name", "color", "icon", "tasks_count", "created_at"]
        read_only_fields = ["id", "created_at"]

    def validate_color(self, value):
        if not value.startswith("#") or len(value) != 7:
            raise serializers.ValidationError("رنگ باید در فرمت hex باشد (مثل #ff0000).")
        return value


class TaskListSerializer(serializers.ModelSerializer):
    category_name = serializers.CharField(source="category.name", read_only=True, default=None)
    category_color = serializers.CharField(source="category.color", read_only=True, default=None)
    is_overdue = serializers.BooleanField(read_only=True)

    class Meta:
        model = Task
        fields = [
            "id", "title", "priority",
            "is_completed", "is_overdue",
            "due_date", "category_name", "category_color",
            "created_at",
        ]


class TaskDetailSerializer(serializers.ModelSerializer):
    category = CategorySerializer(read_only=True)
    is_overdue = serializers.BooleanField(read_only=True)

    class Meta:
        model = Task
        fields = [
            "id", "title", "description", "priority",
            "is_completed", "is_overdue", "completed_at",
            "due_date", "category", "created_at", "updated_at",
        ]


class TaskWriteSerializer(serializers.ModelSerializer):
    class Meta:
        model = Task
        fields = [
            "id", "title", "description", "priority",
            "due_date", "category", "is_completed",
        ]
        read_only_fields = ["id"]

    def validate_due_date(self, value):
        if value and value < timezone.now() and not self.instance:
            raise serializers.ValidationError("تاریخ سررسید نمی‌تواند در گذشته باشد.")
        return value

    def validate_title(self, value):
        value = value.strip()
        if len(value) < 3:
            raise serializers.ValidationError("عنوان باید حداقل ۳ کاراکتر باشد.")
        return value


class TaskStatusSerializer(serializers.Serializer):
    is_completed = serializers.BooleanField()

import django_filters
from django.db.models import Q
from django.utils import timezone
from .models import Task


class TaskFilter(django_filters.FilterSet):
    category = django_filters.UUIDFilter(field_name="category__id")
    priority = django_filters.ChoiceFilter(choices=Task.PRIORITY_CHOICES)
    is_completed = django_filters.BooleanFilter()

    due_after = django_filters.DateFilter(field_name="due_date", lookup_expr="date__gte")
    due_before = django_filters.DateFilter(field_name="due_date", lookup_expr="date__lte")

    overdue = django_filters.BooleanFilter(method="filter_overdue")
    due_today = django_filters.BooleanFilter(method="filter_due_today")
    search = django_filters.CharFilter(method="filter_search")

    class Meta:
        model = Task
        fields = []

    def filter_overdue(self, qs, name, value):
        if value:
            return qs.filter(
                is_completed=False,
                due_date__lt=timezone.now(),
            )
        return qs.exclude(
            is_completed=False,
            due_date__lt=timezone.now(),
        )

    def filter_due_today(self, qs, name, value):
        if not value:
            return qs
        today = timezone.now().date()
        return qs.filter(due_date__date=today)

    def filter_search(self, qs, name, value):
        if not value:
            return qs
        return qs.filter(
            Q(title__icontains=value) | Q(description__icontains=value)
        )

from django.db.models import Count, Q
