from common.permissions import IsOwner
from .models import Category, Task
from .serializers import (
    CategorySerializer,
    TaskListSerializer, TaskDetailSerializer, TaskWriteSerializer,
)
from .filters import TaskFilter


class CategoryViewSet(viewsets.ModelViewSet):
    serializer_class = CategorySerializer
    permission_classes = [IsAuthenticated, IsOwner]
    pagination_class = None

    def get_queryset(self):
        return (
            Category.objects
            .filter(owner=self.request.user)
            .annotate(tasks_count=Count("tasks"))
            .order_by("name")
        )

    def perform_create(self, serializer):
        serializer.save(owner=self.request.user)


class TaskViewSet(viewsets.ModelViewSet):
    permission_classes = [IsAuthenticated, IsOwner]
    filter_backends = [DjangoFilterBackend, filters.SearchFilter, filters.OrderingFilter]
    filterset_class = TaskFilter
    search_fields = ["title", "description"]
    ordering_fields = ["created_at", "due_date", "priority"]
    ordering = ["-created_at"]

    def get_queryset(self):
        return (
            Task.objects
            .filter(owner=self.request.user)
            .select_related("category")
        )

    def get_serializer_class(self):
        if self.action == "list":
            return TaskListSerializer
        if self.action in ("create", "update", "partial_update"):
            return TaskWriteSerializer
        return TaskDetailSerializer

    def perform_create(self, serializer):
        serializer.save(owner=self.request.user)

    @action(detail=True, methods=["post"])
    def toggle(self, request, pk=None):
        """تغییر وضعیت انجام‌شده."""
        task = self.get_object()
        if task.is_completed:
            task.is_completed = False
            task.completed_at = None
            task.save(update_fields=["is_completed", "completed_at"])
        else:
            task.mark_completed()
        return Response(TaskDetailSerializer(task).data)

    @action(detail=False, methods=["get"])
    def stats(self, request):
        """آمار تسک‌های کاربر."""
        qs = Task.objects.filter(owner=request.user)
        now = timezone.now()

        return Response({
            "total": qs.count(),
            "completed": qs.filter(is_completed=True).count(),
            "pending": qs.filter(is_completed=False).count(),
            "overdue": qs.filter(
                is_completed=False,
                due_date__lt=now,
            ).count(),
            "due_today": qs.filter(
                is_completed=False,
                due_date__date=now.date(),
            ).count(),
            "by_priority": list(
                qs.values("priority")
                .annotate(count=Count("id"))
                .order_by("priority")
            ),
        })

    @action(detail=False, methods=["get"])
    def today(self, request):
        """تسک‌های امروز."""
        today = timezone.now().date()
        qs = self.get_queryset().filter(
            due_date__date=today,
            is_completed=False,
        )
        return Response(TaskListSerializer(qs, many=True).data)

    @action(detail=False, methods=["get"])
    def overdue(self, request):
        """تسک‌های دیرکرد."""
        qs = self.get_queryset().filter(
            is_completed=False,
            due_date__lt=timezone.now(),
        )
        return Response(TaskListSerializer(qs, many=True).data)

